def repl(runtime: Runtime) -> int:
    banner_printed = False
    if runtime.stdin_is_tty or runtime.stdout_is_tty:
        sys.stdout.write(VERSION_LINE + "\n")
        sys.stdout.flush()
        banner_printed = True
    buffer = ""
    prompt = "> "
    prompt2 = ">> "
    while True:
        env_prompt = runtime.global_env.rawget("_PROMPT")
        env_prompt2 = runtime.global_env.rawget("_PROMPT2")
        current_prompt = env_prompt if isinstance(env_prompt, str) else prompt
        current_prompt2 = env_prompt2 if isinstance(env_prompt2, str) else prompt2
        sys.stdout.write(current_prompt if not buffer else current_prompt2)
        sys.stdout.flush()
        line = sys.stdin.readline()
        if line == "":
            if not buffer:
                if banner_printed:
                    sys.stdout.write("\n")
                break
            sys.stderr.write(f"stdin:1: unexpected symbol near <eof>\n")
            break
        buffer += line
        if buffer.strip() == "":
            buffer = ""
            continue
        is_expr = False
        try:
            chunk = runtime.compile_chunk(buffer, "stdin")
        except LuaSyntaxError as exc:
            try:
                expr_chunk = runtime.compile_chunk("return " + buffer, "stdin")
                chunk = expr_chunk
                is_expr = True
            except LuaSyntaxError as expr_exc:
                if exc.incomplete or expr_exc.incomplete:
                    continue
                sys.stderr.write(f"stdin:1: {exc.message.split(': ', 1)[-1]}\n")
                buffer = ""
                continue
        try:
            values = runtime.run_top_chunk(chunk, [])
            if is_expr and values:
