        except LuaRuntimeError as err:
            header = err.value if isinstance(err.value, str) else f"(error object is a {lua_type_name(err.value)} value)"
            if isinstance(header, str) and header.startswith("stdin:"):
                sys.stderr.write(header + "\n" + runtime.format_traceback() + "\n")
            else:
                sys.stderr.write(f"{header}\n{runtime.format_traceback()}\n")
        except LuaExit as exc:
            raise exc
        buffer = ""
    return 0


